\item[(c)] Every solution $u\in X^1(\mathbb{R}^N)$ of the equation above belongs to $C^{1,\alpha}_{\mathrm{loc}} (\mathbb{R}^N \setminus \{0\})$ for some $\alpha \in (0,1)$.
\item[(d)] If, in addition, $g$ is H\"older continuous, every solution $u\in X^1(\mathbb{R}^N)$ of the equation above is of the class $C^2 (\mathbb{R}^N\setminus \{0\})$.
\item[(e)] If, in addition, $g$ is odd, there exists a nontrivial, nonnegative, radial and radially nonincreasing solution in $X^1 (\mathbb{R}^N) \cap C^2 (\mathbb{R}^N \setminus \{0\})$ of the equation above, which is a minimizer of $J$ on ${\mathcal M}$.
\item[(f)] Every nonnegative solution of the equation above in $X^1(\mathbb{R}^N) \cap C^2 (\mathbb{R}^N \setminus\{0\})$ does not belong to $H^1 (\mathbb{R}^N)$.
\end{enumerate}

