ref_dict.thm:BKO:
\begin{thm}[\cite{buys2025reconfiguration}] \label{thm:BKO}
Let $G$ be a graph with maximum degree $\Delta$, and let $\cV = \{V_1, \ldots, V_n\}$ be a partition of $V(G)$ such that $|V_i| \ge 2\Delta$ for all $i$. If $G[V_I]$ is not the disjoint union of $|I|$ copies of the complete bipartite graph $K_{\Delta,\Delta}$, for all nonempty $I \subseteq [n]$, then $\recongraph(\cI(G), \cV)$ is connected.
\end{thm}

ref_dict.thm:Tverberg-reconfiguration-1:
\begin{thm} \label{thm:Tverberg-reconfiguration-1}
Let $X$ be a finite set of points in $\mathbb{R}^d$, and let $r \ge 1$ be an integer. If $|X| \ge (d+1)(r-1)+2$, then $\recongraph_{\mathrm{Tv}}(X, r)$ is connected.
\end{thm}

ref_dict.thm:tverberg-homological-connectedness:
\begin{thm} \label{thm:tverberg-homological-connectedness}
Let $X$ be a finite set of points in $\mathbb{R}^d$, and let $r \ge 1$ and $m \ge 0$ be integers. If $|X| \ge (d+1)(r - 1) + m + 1$, then $\mathbf{Tver}(X, r)$ is homologically $(m-1)$-connected.
\end{thm}

